import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[][] cars = new int[n][2];
        for (int i = 0; i < n; i++) {
            cars[i][0] = sc.nextInt();
            cars[i][1] = sc.nextInt();
        }

        int[] arrivals = new int[n];
        int[] departures = new int[n];
        for (int i = 0; i < n; i++) {
            arrivals[i] = cars[i][0];
            departures[i] = cars[i][1];
        }
        Arrays.sort(arrivals);
        Arrays.sort(departures);

        int spots = 0;
        int d = 0;
        for (int a : arrivals) {
            if (a < departures[d]) {
                spots++;
            } else {
                d++;
            }
        }
        System.out.println("Spots: " + spots);
        System.out.println("Open: " + arrivals[0] + " to " + departures[n - 1]);
    }
}
